#include <cstdio>

int a[4], b[4];

int ktra(int x, int y) {
    int defense = a[x];
    int attack = b[y];

    if (defense < b[2] && attack < a[3]) return -1;
    if (defense < b[3] && attack < a[2]) return -1;

    if (defense > b[2] && attack > a[3] &&
        defense > b[3] && attack > a[2]) {
        return 1;
    }

    return 0;
}

int main() {
    for (int i = 0; i < 4; ++i) {
        scanf("%d %d", &a[i], &b[i]);
    }

    int kq1 = ktra(0, 1);
    int kq2 = ktra(1, 0);

    if (kq1 == 1 || kq2 == 1)
        printf("Team 1\n");
    else if (kq1 == 0 || kq2 == 0)
        printf("Draw\n");
    else
        printf("Team 2\n");

    return 0;
}

